package com.schoolmanagement.notification;
import com.schoolmanagement.common.BaseEntity; import com.schoolmanagement.school.School; import com.schoolmanagement.student.Student; import com.schoolmanagement.attendance.AttendanceEvent; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.Instant;
@Entity @Table(name="notifications") @Getter @Setter
public class Notification extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="school_id") private School school; @ManyToOne(optional=false) @JoinColumn(name="student_id") private Student student; @ManyToOne(optional=false) @JoinColumn(name="attendance_event_id") private AttendanceEvent attendanceEvent; @Column(name="recipient_phone",nullable=false) private String recipientPhone; @Column(nullable=false,columnDefinition="text") private String message; @Enumerated(EnumType.STRING) @Column(nullable=false) private NotificationStatus status=NotificationStatus.PENDING; private String providerReference; private int attempts=0; @Column(columnDefinition="text") private String lastError; private Instant sentAt; }
